import time
import logging
from gpiozero import DigitalOutputDevice
from picamera2 import Picamera2, Preview
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput
from gpiozero.pins.spidev import SPI
from gpiozero import MCP3008
import paho.mqtt.client as mqtt
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    def __init__(self, spi_bus=0, spi_device=0, spi_speed_hz=1350000, adc_channel=0, pump_pin=18):
        self.spi = SPI(spi_bus, spi_device, speed_hz=spi_speed_hz)
        self.mcp3008 = MCP3008(adc_channel)
        self.pump = DigitalOutputDevice(pump_pin, active_high=True)
        self.camera = Picamera2()
        self.camera.configure(Picamera2.PreviewConfig())
        self.camera.start_preview(Preview.QTGL)
        self.camera.start_encoder(MJPEGEncoder(FileOutput('output.jpg')))

    def read_moisture(self):
        try:
            # Send the correct SPI command format
            self.spi.write([0x01, 0x80 | adc_channel])
            time.sleep(0.01)
            raw_value = self.spi.read(3)[1]
            return raw_value
        except Exception as e:
            logging.error(f"Error reading moisture: {e}")
            return None

    def run_pump(self, seconds):
        try:
            self.pump.on()
            time.sleep(seconds)
            self.pump.off()
        except Exception as e:
            logging.error(f"Error running pump: {e}")

    def irrigation_cycle(self):
        raw_moisture = self.read_moisture()
        if raw_moisture is not None and raw_moisture > 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        try:
            self.camera.stop_encoder()
            self.camera.stop_preview()
            self.camera.close()
            self.pump.close()
            self.spi.close()
        except Exception as e:
            logging.error(f"Error closing resources: {e}")

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        if controller.irrigation_cycle():
            logging.info("Irrigation cycle completed successfully.")
        else:
            logging.info("Irrigation cycle skipped due to low moisture.")
        time.sleep(interval_seconds)

def main():
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        controller.close()

if __name__ == "__main__":
    main()

import time
import json
import random
import logging
from gpiozero import MCP3008, LED
from picamera2 import Picamera2
from paho.mqtt import client as mqtt
from signal import signal, SIGINT, SIGTERM

# Configure logging
logging.basicConfig(filename='greenhouse_monitor.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize GPIO
moisture_sensor = MCP3008(channel=0, spi=SPI.SpiDev(0, 0))
watering_relay = LED(17)

# Initialize MQTT client
mqtt_client = mqtt.Client()
mqtt_client.on_connect = on_connect
mqtt_client.on_message = on_message
mqtt_client.connect("mqtt.example.com", 1883, 60)

# Initialize camera
camera = Picamera2()
camera.start()

# Load weather forecast
try:
    with open('weather_forecast.json', 'r') as file:
        forecast = json.load(file)
except FileNotFoundError:
    logging.warning("weather_forecast.json not found")
    forecast = None

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        logging.info("Connected to MQTT broker")
        client.subscribe("greenhouse/commands")
    else:
        logging.error("Failed to connect to MQTT broker, return code %d", rc)

def on_message(client, userdata, msg):
    if msg.topic == "greenhouse/commands":
        command = msg.payload.decode()
        if command == "start_watering":
            watering_relay.on()
        elif command == "stop_watering":
            watering_relay.off()

def read_moisture():
    try:
        value = moisture_sensor.value
        if value == 0 or value == 1023:
            logging.warning("Sensor returned extreme values, simulating moisture reading")
            return random.randint(0, 100)
        return value
    except Exception as e:
        logging.error("Error reading moisture sensor: %s", str(e))
        return None

def check_rain_probability(forecast):
    if forecast is None:
        logging.warning("Weather forecast not available")
        return None
    if "rain_probability" not in forecast or not isinstance(forecast["rain_probability"], float) or forecast["rain_probability"] < 0.0 or forecast["rain_probability"] > 1.0:
        logging.warning("Invalid rain_probability value in forecast")
        return None
    return forecast["rain_probability"]

def main():
    while True:
        try:
            moisture = read_moisture()
            if moisture is not None:
                logging.info(f"Moisture reading: {moisture}%")
                rain_probability = check_rain_probability(forecast)
                if rain_probability is not None:
                    logging.info(f"Rain probability: {rain_probability}")
                    if moisture < 30 and rain_probability < 0.2:
                        watering_relay.on()
                        logging.info("Starting watering")
                    elif moisture > 70:
                        watering_relay.off()
                        logging.info("Stopping watering")
                else:
                    logging.warning("Rain probability not available")
            else:
                logging.warning("Failed to read moisture sensor")
        except Exception as e:
            logging.error("Error in main loop: %s", str(e))
        time.sleep(60)

def signal_handler(sig, frame):
    logging.info("Received signal, cleaning up and exiting")
    camera.stop()
    mqtt_client.disconnect()
    watering_relay.close()
    sys.exit(0)

signal(SIGINT, signal_handler)
signal(SIGTERM, signal_handler)

if __name__ == "__main__":
    main()

