import time
import logging
from gpiozero import I2C
from picamera2 import Picamera2
from adafruit_circuitpython_dht import DHT20
import paho.mqtt.client as mqtt
import crc8

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20Sensor:
    def __init__(self, i2c_bus=1, i2c_address=0x40):
        self.i2c = I2C(i2c_bus)
        self.i2c_address = i2c_address
        self.dht20 = DHT20(i2c_address)
        self.status_register = 0x00
        self.crc_polynomial = 0x31
        self.crc_initial_value = 0xFF
        self.retry_count = 5
        self.retry_delay = 2
        self.timeout = 0.1
        self.temperature = None
        self.humidity = None
        self.crc_error_flag = False

    def initialize(self):
        time.sleep(0.5)  # Wait for power stabilization
        status = self.read_status_register()
        if status is None:
            return False
        if status != 0x00:
            logging.error("Status register does not match expected value")
            return False
        return True

    def read_status_register(self):
        try:
            self.i2c.writeto(self.i2c_address, b'\x00')  # Read status register
            status = self.i2c.readfrom(self.i2c_address, 1)[0]
            return status
        except Exception as e:
            logging.error(f"Error reading status register: {e}")
            return None

    def read_data(self):
        try:
            self.i2c.writeto(self.i2c_address, b'\x01')  # Read data
            data = self.i2c.readfrom(self.i2c_address, 7)
            raw_humidity = (data[1] << 16) | (data[2] << 8) | data[3]
            raw_temperature = ((data[3] & 0xF0) << 12) | (data[4] << 8) | data[5]
            crc = data[6]
            calculated_crc = crc8.crc8(data[:6], self.crc_polynomial, self.crc_initial_value)
            if crc != calculated_crc:
                logging.warning("CRC mismatch, discarding data")
                self.crc_error_flag = True
                return None
            self.temperature = raw_temperature / 10.0
            self.humidity = raw_humidity / 10.0
            return (self.temperature, self.humidity, self.crc_error_flag)
        except Exception as e:
            logging.error(f"Error reading data: {e}")
            return None

    def poll_status(self):
        for _ in range(self.retry_count):
            status = self.read_status_register()
            if status is None:
                return False
            if status & 0x80 == 0:
                return True
            time.sleep(self.timeout)
        logging.warning("Status register did not clear within timeout")
        return False

    def read(self):
        if not self.initialize():
            return (None, None, True)
        if not self.poll_status():
            return (None, None, True)
        return self.read_data()

    def cleanup(self):
        self.i2c.close()

    def __del__(self):
        self.cleanup()

# Example usage
if __name__ == "__main__":
    sensor = DHT20Sensor()
    temperature, humidity, crc_error_flag = sensor.read()
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
    else:
        print("Failed to read data")

