        try:
            self.bus = I2C(self.i2c_bus)
            self.dht20 = DHT20(self.bus)
            self.verify_sensor()
        except Exception as e:
            logging.error(f"Failed to initialize DHT20 sensor: {e}")
            self.bus = None

    def verify_sensor(self):
        try:
            status_register = self.dht20.status_register
            if status_register != 0x00:
                logging.error("DHT20 sensor verification failed")
                self.bus = None
        except Exception as e:
            logging.error(f"Failed to verify DHT20 sensor: {e}")
            self.bus = None

    def measure(self):
        if self.bus is None:
            return (None, None, True)

        try:
            self.dht20.measure()
            start_time = time.time()
            while time.time() - start_time < 0.1:
                status_register = self.dht20.status_register
                if status_register & 0x01:
                    break
                time.sleep(0.01)
            else:
                logging.error("DHT20 sensor measurement timed out")
                return (None, None, True)

            humidity_raw = (self.dht20.humidity_raw >> 8) | (self.dht20.humidity_raw << 8)
            temperature_raw = (self.dht20.temperature_raw >> 8) | (self.dht20.temperature_raw << 8)
            crc = self.calculate_crc(humidity_raw, temperature_raw)

            if crc != self.dht20.crc:
                logging.error("DHT20 sensor CRC check failed")
                return (None, None, True)

            return (self.dht20.temperature, self.dht20.humidity, False)
        except Exception as e:
            logging.error(f"Failed to measure DHT20 sensor: {e}")
            return (None, None, True)

    def calculate_crc(self, data1, data2):
        crc = 0x00
        for i in range(6):
            crc ^= data1 >> (5 - i) & 0x01
            for _ in range(8):
                if crc & 0x01:
                    crc = (crc >> 1) ^ 0x8C
                else:
                    crc >>= 1
        return crc

