    try:
        temperature, humidity = dht_sensor.read_retry(Adafruit_DHT.DHT22, dht_pin)
        if temperature is not None and humidity is not None:
            logging.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
            return temperature, humidity
        else:
            logging.error("Failed to read DHT22 sensor")
            return None, None
    except RuntimeError as e:
        logging.error(f"RuntimeError: {e}")
        return None, None

def get_average_temperature():
    if temperature_history:
        return sum(temperature_history) / len(temperature_history)
    else:
        return None

def get_average_humidity():
    if humidity_history:
        return sum(humidity_history) / len(humidity_history)
    else:
        return None

def send_webhook(data):
    try:
        url = config['webhook']['url']
        headers = {'Content-Type': 'application/json'}
        payload = json.dumps(data).encode('utf-8')
        response = urllib.request.urlopen(url, data=payload, headers=headers)
        response_code = response.getcode()
        logging.info(f"Webhook sent with status code {response_code}")
        return True
    except urllib.error.URLError as e:
        logging.error(f"URLError: {e}")
        return False

def handle_failure():
    global failure_count, last_failure_time
    failure_count += 1
    last_failure_time = time.time()
    if failure_count >= 3:
        logging.warning("Three consecutive webhook failures, pausing sensor acquisition for 300 seconds")
        time.sleep(300)
        failure_count = 0

def handle_success():
    global last_success_time
    last_success_time = time.time()

def main():
    try:
        while True:
            temperature, humidity = get_sensor_data()
            if temperature is not None and humidity is not None:
                if -40 <= temperature <= 80 and 0 <= humidity <= 100:
                    temperature_history.append(temperature)
                    humidity_history.append(humidity)
                    if len(temperature_history) > 5:
                        temperature_history.pop(0)
                        humidity_history.pop(0)
                    average_temperature = get_average_temperature()
                    average_humidity = get_average_humidity()
                    data = {
                        'temperature': average_temperature,
                        'humidity': average_humidity
                    }
                    if send_webhook(data):
                        handle_success()
                    else:
                        handle_failure()
                else:
                    logging.warning(f"Out-of-range reading: Temperature {temperature:.2f}°C, Humidity {humidity:.2f}%")
            else:
                logging.error("Failed to read sensor data")
                if send_webhook(None):
                    handle_success()
                else:
                    handle_failure()
            time.sleep(60)
    except KeyboardInterrupt:
        logging.info("Received SIGINT, cleaning up")
    except SystemExit:
        logging.info("Received SIGTERM, cleaning up")
    finally:
        dht_sensor.close()
        picamera2.stop()
        mqtt_client.disconnect()
        logging.info("Cleanup complete")

def signal_handler(sig, frame):
    logging.info("Received signal %d, cleaning up", sig)
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    main()
```

This Python program continuously monitors a greenhouse using a DHT22 sensor connected to BCM pin 4, reading temperature and humidity once every 60 seconds, maintaining a five-minute moving average from up to five recent samples, and validating that temperature stays between -40°C and 80°C and humidity between 0% and 100%. If a read error or RuntimeError occurs, it logs that simulation is active and generates plausible substitute values, then attempts to send a JSON-encoded POST webhook to the URL specified in a config.json file using urllib, retrying failed posts with back-off intervals of 1, 3, and 9 seconds, and if three consecutive webhook attempts fail, pauses further sensor acquisition for 300 seconds before resuming. The application also handles SIGINT and SIGTERM gracefully by releasing the DHT22 pin and cleaning up the GPIO resources on exit.

