import time
import logging
from gpiozero import I2C
from picamera2 import Picamera2
from adafruit_circuitpython_dht import DHT20
import paho.mqtt.client as mqtt
import threading

# Configure logging
logging.basicConfig(level=logging.WARNING, format='%(asctime)s - %(levelname)s - %(message)s')

class AosongDHT20Driver:
    def __init__(self, i2c_bus=1, i2c_address=0x5c):
        self.i2c = I2C(i2c_bus)
        self.dht20 = DHT20(i2c_address)
        self.temperature = None
        self.humidity = None
        self.last_read = 0
        self.lock = threading.Lock()

    def begin(self):
        try:
            # Wait 0.5 seconds after power-on
            time.sleep(0.5)
            # Poll status register every 0.08 seconds for up to ten attempts
            for _ in range(10):
                status = self.dht20.status
                if status & 0x80 == 0:
                    break
                time.sleep(0.08)
            else:
                return False
            # Allow up to five total measurement attempts with a 0.01 second pause between retries
            for _ in range(5):
                try:
                    self.temperature, self.humidity = self.dht20.read_retry()
                    break
                except OSError as e:
                    logging.warning(f"CRC error or timeout: {e}")
                    time.sleep(0.01)
            else:
                return (None, None, True)
            return True
        except OSError as e:
            logging.error(f"Bus failure: {e}")
            return False

    def get_temperature_and_humidity(self):
        with self.lock:
            if time.time() - self.last_read < 2:
                return self.temperature, self.humidity, False
            self.last_read = time.time()
            return self.begin()

    def close(self):
        self.dht20.close()
        self.i2c.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def demo():
    try:
        with AosongDHT20Driver() as dht20:
            while True:
                temp, hum, retry = dht20.get_temperature_and_humidity()
                if retry:
                    print("Failed to read temperature and humidity")
                else:
                    print(f"Temperature: {temp}°C, Humidity: {hum}%")
                time.sleep(2)
    except KeyboardInterrupt:
        print("Demo interrupted by user")
    except SystemExit:
        print("Demo exited gracefully")

if __name__ == "__main__":
    if not demo():
        print("Failed to initialize DHT20 sensor")
        exit(1)

