import time
from gpiozero import RotaryEncoder
from picamera2 import Picamera2
from paho.mqtt import client as mqtt
import threading

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None, debounce_interval=0.005):
        if not callable(callback):
            raise ValueError("Callback must be callable")
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.debounce_interval = debounce_interval
        self.current_state = None
        self.previous_state = None
        self.counter = 0
        self.encoder = RotaryEncoder(clk_pin, dt_pin, pull_up=True)
        self.encoder.when_rotated = self._on_rotation
        self.thread = threading.Thread(target=self._run)
        self.thread.start()

    def _on_rotation(self, pin):
        if pin == self.clk_pin:
            self.current_state = self.encoder.value

    def _run(self):
        while True:
            time.sleep(self.debounce_interval)
            if self.current_state != self.previous_state:
                self.previous_state = self.current_state
                if self.callback:
                    try:
                        self.callback(self.counter)
                    except Exception as e:
                        print(f"Callback error: {e}")
                if self.current_state == 1:
                    self.counter += 1
                else:
                    self.counter -= 1

    def cleanup(self):
        self.encoder.close()
        self.thread.join()

class Camera:
    def __init__(self, resolution=(1920, 1080), framerate=30):
        self.camera = Picamera2()
        self.camera.resolution = resolution
        self.camera.framerate = framerate
        self.camera.start()

    def capture(self):
        return self.camera.capture_array("main")

    def stop(self):
        self.camera.stop()

class MQTTClient:
    def __init__(self, broker, port, client_id, username, password):
        self.client = mqtt.Client(client_id)
        self.client.username_pw_set(username, password)
        self.client.connect(broker, port)
        self.client.loop_start()

    def publish(self, topic, payload):
        self.client.publish(topic, payload)

    def disconnect(self):
        self.client.disconnect()
        self.client.loop_stop()

def main():
    try:
        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=lambda x: print(f"Counter: {x}"))
        camera = Camera()
        mqtt_client = MQTTClient(broker="mqtt.example.com", port=1883, client_id="rotary_encoder", username="user", password="pass")

        while True:
            image = camera.capture()
            mqtt_client.publish("rotary_encoder/image", image)
            time.sleep(1)

    except KeyboardInterrupt:
        print("KeyboardInterrupt detected, cleaning up...")
    finally:
        encoder.cleanup()
        camera.stop()
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

