import RPi.GPIO as GPIO
import picamera2
import time
import signal
import sys
from gpiozero import LED
from paho.mqtt import client as mqtt

class LEDController:
    def __init__(self, pin=25):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(pin, GPIO.OUT)
            self.led = LED(pin)
        except ValueError as e:
            print(f"Error: {e}")
            sys.exit(1)
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
            sys.exit(1)

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("On and off durations must be non-negative.")
        try:
            self.on()
            time.sleep(on_duration)
            self.off()
            time.sleep(off_duration)
        except Exception as e:
            print(f"An error occurred during blinking: {e}")

def signal_handler(sig, frame):
    print("Received signal, turning LED off and exiting...")
    controller.off()
    GPIO.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    try:
        controller = LEDController()
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        while True:
            controller.blink(1.0, 0.5)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        controller.off()
        GPIO.cleanup()

