import time
import atexit
from gpiozero import PWMOutputDevice
from picamera2 import Picamera2
from adafruit_pca9685 import PCA9685
import paho.mqtt.client as mqtt

class Fuchikoma:
    def __init__(self):
        try:
            self.pca = PCA9685(i2c_bus=1)
            self.pca.frequency = 60
            self.pca.set_pwm_range(0, 150, 600)
            self.channels = {
                'claw': 0,
                'lock': 1,
                'water_gun': 2
            }
            self.camera = Picamera2()
            self.camera.start()
            atexit.register(self.cleanup)
        except (ValueError, OSError) as e:
            print(f"PCA9685 not found: {e}")
            exit(1)

    def move_servo(self, channel, angle):
        if channel not in self.channels:
            raise ValueError(f"Invalid channel: {channel}")
        if not (-77 <= angle <= 77):
            raise ValueError(f"Angle out of range: {angle}")
        pulse_width = self.angle_to_pulse_width(angle)
        self.pca.set_pwm(self.channels[channel], 0, pulse_width)
        time.sleep(0.029)
        self.pca.set_pwm(self.channels[channel], 0, 0)

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        for channel in self.channels.values():
            self.pca.set_pwm(channel, 0, 0)
        self.camera.stop()
        self.pca.deinit()

    def angle_to_pulse_width(self, angle):
        return int((angle + 77) * (600 - 150) / 154 + 150)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker")
    else:
        print(f"Failed to connect, return code {rc}")

def on_message(client, userdata, msg):
    print(f"Received message: {msg.payload.decode()} on topic {msg.topic}")

if __name__ == "__main__":
    fuchikoma = Fuchikoma()
    client = mqtt.Client()
    client.on_connect = on_connect
    client.on_message = on_message
    client.connect("mqtt.example.com", 1883, 60)
    client.loop_start()

    try:
        while True:
            # Example usage
            fuchikoma.bite()
            time.sleep(1)
            fuchikoma.open_claw()
            time.sleep(1)
            fuchikoma.lock()
            time.sleep(1)
            fuchikoma.unlock()
            time.sleep(1)
            fuchikoma.shoot()
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        client.loop_stop()
        fuchikoma.cleanup()

import time
from gpiozero import PWMOutputDevice
from picamera2 import Picamera2
from adafruit_circuitpython_*. import *
import paho.mqtt.client as mqtt
import threading

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, driver, pin):
        if not isinstance(driver, PWMOutputDevice):
            raise MotorError("Invalid driver library.pi instance")
        if not isinstance(pin, int):
            raise MotorError("Pin number must be an integer")
        if pin < 0 or pin > 255:
            raise MotorError("Pin number must be in the range 0-255")

        self.driver = driver
        self.pin = pin
        self.driver.mode = PWMOutputDevice.OUT
        self.driver.frequency = 1000
        self.driver.duty_cycle = 0

    def set_frequency(self, freq):
        if not isinstance(freq, int):
            raise MotorError("Frequency must be an integer")
        if freq < 0 or freq > 10000:
            raise MotorError("Frequency must be in the range 0-10000 Hz")

        try:
            self.driver.frequency = freq
        except Exception as e:
            raise MotorError(f"Failed to set frequency: {e}")

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int):
            raise MotorError("Duty cycle must be an integer")
        if duty < 0 or duty > 255:
            raise MotorError("Duty cycle must be in the range 0-255")

        try:
            self.driver.duty_cycle = duty
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle: {e}")

    def stop(self):
        self.set_duty_cycle(0)

    def __del__(self):
        self.stop()

    def close(self):
        self.driver.close()

