import serial
import time
from gpiozero import Servo
from picamera2 import Picamera2
from adafruit_circuitpython_busio import I2C
from adafruit_mcp3008 import MCP3008
from paho.mqtt import client as mqtt
import signal
import sys

# Define error codes
ERROR_OK = 0
ERROR_SERIAL_PORT_NOT_FOUND = 1
ERROR_MODBUS_EXCEPTION = 2
ERROR_TIMEOUT = 3
ERROR_SENSOR_ABSENT = 4
ERROR_BUS_ERROR = 5

class ModbusRTUServo:
    def __init__(self, serial_port, baud_rate=115200, timeout=1):
        self.serial_port = serial_port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial = None
        self.servo = None
        self.camera = None
        self.mcp3008 = None
        self.mqtt_client = None

        # Initialize serial port
        try:
            self.serial = serial.Serial(self.serial_port, self.baud_rate, timeout=self.timeout)
        except serial.SerialException as e:
            print(f"Error opening serial port {self.serial_port}: {e}")
            sys.exit(ERROR_SERIAL_PORT_NOT_FOUND)

        # Initialize servo
        try:
            self.servo = Servo(18)  # Assuming GPIO 18 is connected to the servo
        except Exception as e:
            print(f"Error initializing servo: {e}")
            sys.exit(ERROR_SERVO_INIT_FAILED)

        # Initialize camera
        try:
            self.camera = Picamera2()
            self.camera.start()
        except Exception as e:
            print(f"Error initializing camera: {e}")
            sys.exit(ERROR_CAMERA_INIT_FAILED)

        # Initialize MCP3008
        try:
            self.mcp3008 = MCP3008(I2C(1))
        except Exception as e:
            print(f"Error initializing MCP3008: {e}")
            sys.exit(ERROR_MCP3008_INIT_FAILED)

        # Initialize MQTT client
        try:
            self.mqtt_client = mqtt.Client()
            self.mqtt_client.on_connect = self.on_connect
            self.mqtt_client.on_message = self.on_message
            self.mqtt_client.connect("mqtt.example.com", 1883, 60)
        except Exception as e:
            print(f"Error initializing MQTT client: {e}")
            sys.exit(ERROR_MQTT_INIT_FAILED)

    def on_connect(self, client, userdata, flags, rc):
        print(f"Connected with result code {rc}")

    def on_message(self, client, userdata, msg):
        print(f"Received message: {msg.payload.decode()} on topic {msg.topic}")

    def move_servo(self, angle):
        if not (0 <= angle <= 180):
            print("Angle must be between 0 and 180 degrees")
            return ERROR_INVALID_ANGLE

        try:
            self.servo.value = angle / 180.0
            time.sleep(1)  # Wait for servo to move
        except Exception as e:
            print(f"Error moving servo: {e}")
            return ERROR_SERVO_MOVE_FAILED

        return ERROR_OK

    def read_camera(self):
        try:
            image = self.camera.capture_array()
            return image
        except Exception as e:
            print(f"Error reading camera: {e}")
            return None

    def read_mcp3008(self, channel):
        try:
            return self.mcp3008.read(channel)
        except Exception as e:
            print(f"Error reading MCP3008: {e}")
            return None

    def publish_mqtt(self, topic, message):
        try:
            self.mqtt_client.publish(topic, message)
        except Exception as e:
            print(f"Error publishing MQTT message: {e}")
            return ERROR_MQTT_PUBLISH_FAILED

    def cleanup(self):
        if self.serial:
            self.serial.close()
        if self.servo:
            self.servo.close()
        if self.camera:
            self.camera.stop()
        if self.mcp3008:
            self.mcp3008.deinit()
        if self.mqtt_client:
            self.mqtt_client.disconnect()

def signal_handler(sig, frame):
    print("Exiting...")
    sys.exit(0)

if __name__ == '__main__':
    try:
        # Create ModbusRTUServo instance
        servo = ModbusRTUServo('/dev/serial0')

        # Demonstration
        print("Moving servo to 90 degrees...")
        result = servo.move_servo(90)
        if result == ERROR_OK:
            print("Servo moved successfully.")
        else:
            print(f"Failed to move servo: {result}")

        print("Reading camera...")
        image = servo.read_camera()
        if image is not None:
            print("Camera read successfully.")
        else:
            print("Failed to read camera.")

        print("Reading MCP3008 channel 0...")
        value = servo.read_mcp3008(0)
        if value is not None:
            print(f"MCP3008 channel 0 value: {value}")
        else:
            print("Failed to read MCP3008.")

        print("Publishing MQTT message...")
        result = servo.publish_mqtt("test/topic", "Hello, MQTT!")
        if result == ERROR_OK:
            print("MQTT message published successfully.")
        else:
            print(f"Failed to publish MQTT message: {result}")

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        servo.cleanup()
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        signal.pause()

