import picamera2
import paho.mqtt.client as mqtt
from gpiozero import DigitalOutputDevice
from adafruit_circuitpython_busio import I2C
from adafruit_ds1338 import DS1338

class DS1338RTC:
    def __init__(self):
        try:
            self.i2c = I2C(1)
            self.rtc = DS1338(self.i2c)
        except OSError as e:
            raise IOError(f"Failed to open I2C bus: {e}")

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def close(self):
        if self.i2c:
            self.i2c.deinit()
            self.i2c = None

    def read_all(self):
        try:
            registers = self.rtc.datetime
            year = registers[0] + 2000
            month = registers[1]
            date = registers[2]
            day = registers[3]
            hours = registers[4]
            minutes = registers[5]
            seconds = registers[6]
            return year, month, date, day, hours, minutes, seconds
        except OSError as e:
            raise IOError(f"Failed to read RTC registers: {e}")

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime.datetime(year, month, date, hours, minutes, seconds, tzinfo=datetime.timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (2000 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (0 <= day <= 6):
            raise ValueError("Day of the week must be between 0 and 6")
        if not (0 <= hours <= 23):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes <= 59):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds <= 59):
            raise ValueError("Seconds must be between 0 and 59")

        bcd_seconds = self._bcd_encode(seconds)
        bcd_minutes = self._bcd_encode(minutes)
        bcd_hours = self._bcd_encode(hours)
        bcd_day = self._bcd_encode(day)
        bcd_month = self._bcd_encode(month)
        bcd_year = self._bcd_encode(year - 2000)

        registers = [
            bcd_year,
            bcd_month,
            bcd_date,
            bcd_day,
            bcd_hours,
            bcd_minutes,
            bcd_seconds
        ]

        try:
            self.rtc.datetime = registers
        except OSError as e:
            raise IOError(f"Failed to write RTC registers: {e}")

    def write_datetime(self, dt):
        year = dt.year - 2000
        month = dt.month
        date = dt.day
        day = dt.weekday()
        hours = dt.hour
        minutes = dt.minute
        seconds = dt.second
        self.write_all(year, month, date, day, hours, minutes, seconds)

    def write_now(self):
        self.write_datetime(datetime.datetime.now())

    def _bcd_encode(self, value):
        return (value // 10) << 4 | (value % 10)

    def _bcd_decode(self, value):
        return (value >> 4) * 10 + (value & 0xF)

if __name__ == "__main__":
    try:
        with DS1338RTC() as rtc:
            current_time = rtc.read_datetime()
            print(f"Current time: {current_time}")
    except IOError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(0)

