from adafruit_circuitpython_esp8266 import ESP8266

class ESP8266Control:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        try:
            self.ser = serial.Serial(port, baud_rate, timeout=timeout)
            self.ser.flushInput()
            self.ser.flushOutput()
            self._send_command('AT', timeout=1.0)
            self.test_connection()
        except serial.SerialException as e:
            print(f"Failed to open UART port: {e}")
            self.ser = None

    def _send_command(self, command, terminator=b'OK', timeout=1.0):
        if self.ser is None:
            return None
        self.ser.write(command.encode() + b'\r\n')
        start_time = time.time()
        while time.time() - start_time < timeout:
            response = self.ser.readline()
            if response.startswith(terminator):
                return response
        return None

    def test_connection(self):
        response = self._send_command('AT')
        if response and response.startswith(b'OK'):
            print("Connection test passed.")
        else:
            print("Connection test failed.")

    def restart(self):
        self._send_command('AT+RST')
        time.sleep(2)
        self.test_connection()

    def connect_wifi(self, ssid, password, timeout=10.0):
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command, timeout=timeout)
        if response and response.startswith(b'OK'):
            print("WiFi connection successful.")
        else:
            print("WiFi connection failed.")

    def disconnect_wifi(self):
        self._send_command('AT+CWQAP')
        print("WiFi disconnected.")

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        if response:
            lines = response.decode().splitlines()
            for line in lines:
                if line.startswith('STAIP:'):
                    return line.split(':')[1].strip()
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = {}
        headers_str = '\r\n'.join(f'{key}: {value}' for key, value in headers.items())
        request = f'{method} {url} HTTP/1.1\r\nHost: {host}\r\n{headers_str}\r\n\r\n'
        if data:
            request += data
        self._send_command(f'AT+CIPSTART="TCP","{host}",{port}')
        self._send_command(f'AT+CIPSEND={len(request)}')
        self.ser.write(request.encode())
        response = self._send_command('AT+CIPCLOSE')
        return response

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        while time.time() - start_time < timeout:
            response = self.ser.readline()
            if response.startswith(b'+IPD'):
                parts = response.decode().split(':')
                if len(parts) == 3:
                    length = int(parts[1])
                    payload = self.ser.read(length)
                    return payload
            elif response.startswith(b'CLOSED'):
                return None
        return None

    def signal_handler(self, signum, frame):
        if self.ser:
            self.ser.close()
        print("UART port closed.")

if __name__ == "__main__":
    import signal
    signal.signal(signal.SIGINT, ESP8266Control.signal_handler)
    signal.signal(signal.SIGTERM, ESP8266Control.signal_handler)

    esp = ESP8266Control()
    if esp.ser:
