class GPSController:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        try:
            self.ser = serial.Serial(port, baud, timeout=1)
        except serial.SerialException as e:
            raise ValueError(f"Failed to open serial port {port}: {e}")
        self.gps_on = False
        self.camera = Picamera2()
        self.camera.configure(self.camera.create_still_configuration(main={"size": (1920, 1080), "format": "jpeg"}))
        self.camera.start()
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message
        self.mqtt_client.connect("mqtt.example.com", 1883, 60)
        self.mqtt_client.loop_start()

    def attach(self):
        if not self.gps_on:
            self.ser.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            response = self.ser.readline().decode().strip()
            if response == 'OK':
                self.gps_on = True
                print("GPS module powered on.")
            else:
                raise ValueError(f"Failed to power on GPS module: {response}")

    def detach(self):
        if self.gps_on:
            self.ser.write(b'AT+CGNSPWR=0\r\n')
            time.sleep(1)
            response = self.ser.readline().decode().strip()
            if response == 'OK':
                self.gps_on = False
                print("GPS module powered off.")
            else:
                raise ValueError(f"Failed to power off GPS module: {response}")

    def get_data(self):
        try:
            data = self.ser.readline().decode().strip()
            if data.startswith('$GPRMC'):
                parts = data.split(',')
                if parts[2] == 'A':
                    return parts
        except serial.SerialException as e:
            print(f"Error reading from serial port: {e}")
        return None

    def close(self):
        self.mqtt_client.loop_stop()
        self.mqtt_client.disconnect()
        self.camera.stop()
        self.ser.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def on_connect(self, client, userdata, flags, rc):
        print(f"Connected with result code {rc}")

    def on_message(self, client, userdata, msg):
        print(f"Received message: {msg.payload.decode()} on topic {msg.topic}")

def signal_handler(sig, frame):
    print("Received signal, closing gracefully...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GPSController() as gps:
        try:
            gps.attach()
            while True:
                data = gps.get_data()
                if data:
                    print("Received GPS data:", data)
                    # Example: Publish data to MQTT
                    gps.mqtt_client.publish("gps/data", ','.join(data))
                time.sleep(1)
        except Exception as e:
            print(f"An error occurred: {e}")

