class SimpleGPS:
    def __init__(self):
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial('/dev/serial0', 9600, timeout=1, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE, bytesize=serial.EIGHTBITS)
            logging.info("GPS module connected successfully.")
            return True
        except OSError as e:
            logging.error(f"Failed to connect to GPS module: {e}")
            return False

    def read_data(self):
        if self.ser is None:
            logging.error("GPS module is not connected.")
            return None
        try:
            data = self.ser.readline().decode('utf-8', errors='ignore').strip()
            return data
        except Exception as e:
            logging.error(f"Failed to read data from GPS module: {e}")
            return None

    def parse_gga(self, line):
        if not line.startswith('$GPGGA') and not line.startswith('$GNGGA'):
            return None
        try:
            fields = line.split(',')
            utc_time = fields[1]
            latitude = float(fields[2]) if fields[2] else None
            longitude = float(fields[4]) if fields[4] else None
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Failed to parse GGA sentence: {e}")
            return None

    def close(self):
        if self.ser is not None:
            try:
                self.ser.close()
                logging.info("GPS module connection closed.")
            except Exception as e:
                logging.error(f"Failed to close GPS module connection: {e}")
            self.ser = None

