    gps = SimpleGPS()
    if not gps.connect():
        return

    try:
        while True:
            data = gps.read_data()
            if data:
                gga_data = gps.parse_gga(data)
                if gga_data:
                    logging.info(json.dumps(gga_data, indent=4))
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt detected. Closing GPS module connection.")
    finally:
        gps.close()

if __name__ == "__main__":
